REPLACE INTO authors (id, name, latin_name, title, years, birth_year, death_year, description, hero_image, theme, color, highlights) VALUES ('caesar', 'Gaius Julius Caesar', 'Gaius Iulius Caesar', 'Dictator Perpetuo', '100 – 44 v. Chr.', -100, -44, 'Feldherr, Staatsmann und Autor. Eroberer Galliens und Begründer des Übergangs von der Römischen Republik zum Kaiserreich.', '/images/caesar-hero.jpg', 'theme-caesar', 'hsl(25, 95%, 53%)', '[{"title":"De Bello Gallico","description":"Der Gallische Krieg – Strategie, Propaganda und Expansion.","link":"/caesar/works/de-bello-gallico","icon":"book"},{"title":"De Bello Civili","description":"Der Bürgerkrieg gegen Pompeius – Macht und Rechtfertigung.","link":"/caesar/works/de-bello-civili","icon":"scroll"},{"title":"Gallienkarte","description":"Kampagnenkarte und Schlüsselorte der Eroberung.","link":"/timeline","icon":"map"}]');
REPLACE INTO authors (id, name, latin_name, title, years, birth_year, death_year, description, hero_image, theme, color, highlights) VALUES ('cicero', 'Marcus Tullius Cicero', 'Marcus Tullius Cicero', 'Consul, Orator, Philosophus', '106 – 43 v. Chr.', -106, -43, 'Der bedeutendste Redner Roms, Staatsmann, Philosoph und Verteidiger der Republik. Prägte die lateinische Prosa und die abendländische Rhetorik.', '/images/cicero-hero.jpg', 'theme-cicero', 'hsl(210, 80%, 50%)', '[{"title":"In Catilinam","description":"Vier Reden gegen Catilina – Rhetorik auf höchstem Niveau.","link":"/cicero/works/in-catilinam","icon":"megaphone"},{"title":"De Officiis","description":"Über Pflichten – Ethik und Tugenden im Leben.","link":"/cicero/works/de-officiis","icon":"feather"},{"title":"De Re Publica","description":"Der ideale Staat – Verfassung, Gerechtigkeit, Gemeinwohl.","link":"/cicero/works/de-re-publica","icon":"columns"}]');
REPLACE INTO authors (id, name, latin_name, title, years, birth_year, death_year, description, hero_image, theme, color, highlights) VALUES ('augustus', 'Augustus', 'Imperator Caesar Divi Filius Augustus', 'Princeps, Erster römischer Kaiser', '63 v. Chr. – 14 n. Chr.', -63, 14, 'Großneffe und Adoptivsohn Caesars. Begründer des Römischen Kaiserreichs (Prinzipat), der nach Jahrzehnten des Bürgerkriegs eine neue Ära des Friedens einleitete.', '/images/augustus-hero.jpg', 'theme-augustus', 'hsl(280, 70%, 55%)', '[{"title":"Res Gestae","description":"Der Rechenschaftsbericht des Princeps – Monument und Selbstbild.","link":"/augustus/works/res-gestae","icon":"tablet"},{"title":"Der Prinzipat","description":"Neue Ordnung nach dem Bürgerkrieg – Macht und Stabilität.","link":"/timeline","icon":"crown"}]');
REPLACE INTO authors (id, name, latin_name, title, years, birth_year, death_year, description, hero_image, theme, color, highlights) VALUES ('catilina', 'Lucius Sergius Catilina', 'Lucius Sergius Catilina', 'Patricius, Coniurator', '108 – 62 v. Chr.', -108, -62, 'Römischer Politiker und Kopf der nach ihm benannten Verschwörung von 63 v. Chr. Er versuchte durch einen Umsturz die Macht in Rom zu erringen.', '/images/catilina-hero.jpg', 'theme-caesar', 'hsl(0, 70%, 40%)', '[]');
REPLACE INTO authors (id, name, latin_name, title, years, birth_year, death_year, description, hero_image, theme, color, highlights) VALUES ('seneca', 'Lucius Annaeus Seneca', 'Lucius Annaeus Seneca', 'Philosophus, Stoicus', '4 v. Chr. – 65 n. Chr.', -4, 65, 'Einer der meistgelesenen Schriftsteller seiner Zeit, stoischer Philosoph, Naturforscher und Staatsmann. Erzieher und Berater des jungen Nero.', '/images/seneca-hero.jpg', 'theme-cicero', 'hsl(140, 40%, 40%)', '[{"title":"Epistulae Morales","description":"124 Briefe über Ethik – Zeitlose stoische Weisheit.","link":"/seneca/works/epistulae-morales","icon":"scroll"},{"title":"De Brevitate Vitae","description":"Über die Kürze des Lebens – Ein Essay über Zeitnutzung.","link":"/seneca/works/de-brevitate-vitae","icon":"clock"},{"title":"De Clementia","description":"Über die Milde – Ein Fürstenspiegel für Nero.","link":"/seneca/works/de-clementia","icon":"heart"}]');
